                <span class="arrow">▼</span>
            </div>
            <div class="section-content">
                <div class="property">
                    <div class="property-name">当前位置</div>
                    <div class="property-value-container">
                        <span class="value-main" id="world-location">未知</span>
                    </div>
                </div>
                <div class="property">
                    <div class="property-name">时间 / 天气</div>
                    <div class="property-value-container">
                        <span class="value-main" id="world-time">--</span>
                        <span class="value-secondary" id="world-weather">--</span>
                    </div>
                </div>
            </div>
        </div>

