            <div class="section-header" onclick="toggleSection(this)">
                <span>元素契约</span>
                <span class="arrow">▼</span>
            </div>
            <div class="section-content">
                <div id="elemental-debts-list" class="debt-list">
                    <p>暂无债务。</p>
                </div>
            </div>
        </div>
    </div>
</div>

<script>
    function updateProgressBar(barId, valueId, rawValue, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueDisplay = document.getElementById(valueId);

        let numericValue = parseFloat(Array.isArray(rawValue) ? rawValue[0] : rawValue);
        if (isNaN(numericValue)) numericValue = min;

        if (valueDisplay) valueDisplay.innerText = String(Array.isArray(rawValue) ? rawValue[0] : rawValue);

        if (progressBar) {
            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            progressBar.style.backgroundColor = color || 'var(--accent-color-main)';
        }
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red;padding:10px;'>无法加载状态数据。</p>";
                return;
            }
            const characterData = messages[0].data.display_data || messages[0].data.stat_data;

            // Update Luo's Status
            const luoData = characterData?.角色?.洛;
            if (luoData) {
                updateProgressBar('luo-affinity-bar', 'luo-affinity', luoData.好感度与信赖度, -100, 101, 'var(--accent-color-luo)');
                updateProgressBar('luo-satiety-bar', 'luo-satiety', luoData.饱腹度, 0, 100);
                updateProgressBar('luo-fatigue-bar', 'luo-fatigue', luoData.疲劳度, 0, 100);
                updateProgressBar('luo-cleanliness-bar', 'luo-cleanliness', luoData.清洁度, 0, 100);
            }

            // Update User's Status
            const userData = characterData?.角色?.['{{User}}'];
            if (userData) {
                updateProgressBar('user-satiety-bar', 'user-satiety', userData.饱腹度, 0, 100, 'var(--accent-color-user)');
                updateProgressBar('user-fatigue-bar', 'user-fatigue', userData.疲劳度, 0, 100, 'var(--accent-color-user)');
                updateProgressBar('user-cleanliness-bar', 'user-cleanliness', userData.清洁度, 0, 100, 'var(--accent-color-user)');
            }

            // Update World Status
            const worldData = characterData?.世界;
            const locationData = userData?.当前位置?.[0];
            if (worldData) {
                document.getElementById('world-time').innerText = worldData.时间?.[0] || '--';
                document.getElementById('world-weather').innerText = worldData.天气?.[0] || '--';
            }
            if (locationData && typeof locationData === 'object') {
                const locationString = [locationData.区域, locationData.地点, locationData.具体建筑]
                    .filter(part => part && part !== '无')
                    .join(' - ');
                document.getElementById('world-location').innerText = locationString || '未知';
            }

            // Update Elemental Debts
            const debtListContainer = document.getElementById('elemental-debts-list');
            const debts = characterData?.元素契约?.当前债务?.[0];
            if (debtListContainer) {
                debtListContainer.innerHTML = '';
                if (debts && debts.length > 0) {
                    debts.forEach(debt => {
                        const debtItem = document.createElement('div');
                        debtItem.className = 'debt-item';
                        debtItem.innerHTML = `<strong>精灵 ${debt[0]}:</strong> ${debt[1]} (剩余 <strong>${debt[2]}</strong> 天)`;
                        debtListContainer.appendChild(debtItem);
                    });
                } else {
                    debtListContainer.innerHTML = '<p>暂无债务。</p>';
                }
            }

        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red;padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('.arrow');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
    }

    // Auto-expand the first section by default
    document.addEventListener('DOMContentLoaded', () => {
        initDisplay();
        const firstSectionHeader = document.querySelector('.section-header');
        if(firstSectionHeader) {
            toggleSection(firstSectionHeader);
        }
    });
</script>
</body>
</html>
